import{_ as a,o as s,c as n,a5 as p}from"./chunks/framework.CslsFoWx.js";const t="/VendoraSystem-docs/captures/2026-10-30-dette-technique/android-02-mise-a-jour-requise.png",r="/VendoraSystem-docs/captures/2026-10-30-dette-technique/ios-02-mise-a-jour-requise.png",o="/VendoraSystem-docs/captures/2026-10-30-dette-technique/web-01-dashboard-latence-des-caisses.jpg",h=JSON.parse('{"title":"Lot 2.27 — Dette technique avant la phase 3 (pense-bête §5) — 30/10/2026","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-10-30-dette-technique.md","filePath":"generated/preuves/2026-10-30-dette-technique.md","lastUpdated":null}'),i={name:"preuves/2026-10-30-dette-technique.md"};function c(l,e,d,u,m,g){return s(),n("div",null,[...e[0]||(e[0]=[p('<h1 id="lot-2-27-—-dette-technique-avant-la-phase-3-pense-bete-§5-—-30-10-2026" tabindex="-1">Lot 2.27 — Dette technique avant la phase 3 (pense-bête §5) — 30/10/2026 <a class="header-anchor" href="#lot-2-27-—-dette-technique-avant-la-phase-3-pense-bete-§5-—-30-10-2026" aria-label="Permalink to &quot;Lot 2.27 — Dette technique avant la phase 3 (pense-bête §5) — 30/10/2026&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-10-30-dette-technique</code> · 3 image(s) · 3 trace(s)</p><div><p>Vraie stack : serveur local (migration <strong>V30</strong> appliquée au redémarrage, <code>pos.app.min-version = 0.1.0</code>), back-office Angular (OWNER <code>omar@epicerie.tn</code>), émulateur Android « Caisse-Android-2 » (app 0.1.0), simulateur iPhone (app 1.0). Cinq dettes soldées : <strong>version minimale d&#39;app</strong> (426), <strong>télémétrie de latence</strong> jusqu&#39;au tableau de bord, <strong>phase Xcode</strong> qui reconstruit le XCFramework, <strong>tokens d&#39;espacement</strong> Android, <strong>vraie sauvegarde / restauration</strong> tentée.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;il faut voir</th></tr></thead><tbody><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-dette-technique/api-01-version-minimale-426-telemetrie.txt">api-01-version-minimale-426-telemetrie.txt</a></td><td>API : <code>X-App-Version: 0.0.9</code> → <strong>426</strong> <code>{UPGRADE_REQUIRED, minAppVersion 0.1.0, message}</code> ; sans en-tête → 426 ; <code>0.1.0</code> → 200 ; <code>/pos/lan-key</code> aussi couvert ; le JWT back-office n&#39;est pas concerné ; deux rapports de latence (202) → le back-office lit le <strong>dernier</strong> par appareil et action (p95 recherche 142 → 38 ms, « dans le budget »)</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-dette-technique/web-01-dashboard-latence-des-caisses.jpg">web-01-dashboard-latence-des-caisses.jpg</a></td><td>Tableau de bord, nouvelle carte <strong>« Latence des caisses »</strong> : 3 appareils (Caisse-Android-2 android 0.1.0, iPhone ios 1.0, Preuve API), p50 / p95 / max par action, <strong>1 action hors budget</strong> en rouge (recherche Android sur l&#39;émulateur, 1 423 ms — mesure réelle de l&#39;émulateur, pas d&#39;une tablette), reçu le</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-dette-technique/android-02-mise-a-jour-requise.png">android-02-mise-a-jour-requise.png</a></td><td>Android, serveur temporairement en <code>min-version 2.0.0</code> : à la place de « Mode hors-ligne », le bandeau <strong>« Mise à jour requise : version minimale 2.0.0 — l&#39;app continue hors ligne, synchronisation suspendue »</strong> ; la caisse reste utilisable</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-dette-technique/ios-02-mise-a-jour-requise.png">ios-02-mise-a-jour-requise.png</a></td><td>iPhone, même situation : même message sur l&#39;écran « Qui êtes-vous ? » (parité)</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-dette-technique/android-01-restauration-sauvegarde-refusee.txt">android-01-restauration-sauvegarde-refusee.txt</a></td><td><strong>Vraie</strong> sauvegarde sur l&#39;émulateur : <code>bmgr backupnow pos.android</code> → <strong>« Backup is not allowed »</strong>, <code>adb backup</code> → archive de <strong>0 octet</strong>, aucun jeu de sauvegarde à restaurer, base locale intacte</td></tr><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-dette-technique/ios-01-exclusion-sauvegarde-attributs-fichiers.txt">ios-01-exclusion-sauvegarde-attributs-fichiers.txt</a></td><td>Conteneur réel de l&#39;app iOS : attribut <code>com.apple.metadata:com_apple_backup_excludeItem</code> présent sur le <strong>dossier</strong> <code>databases</code> et sur <code>pos.db</code> / <code>pos.db-wal</code> (posé par <code>isExcludedFromBackup</code>)</td></tr></tbody></table><h2 id="phase-xcode-xcframework-reconstruit-par-le-build" tabindex="-1">Phase Xcode (XCFramework reconstruit par le build) <a class="header-anchor" href="#phase-xcode-xcframework-reconstruit-par-le-build" aria-label="Permalink to &quot;Phase Xcode (XCFramework reconstruit par le build)&quot;">​</a></h2><p>Journal <code>xcodebuild test</code> après modification de <code>:shared</code> : <code>Shared.xcframework périmé (ex. shared/src/commonMain/kotlin/pos/shared/sync/AppVersion.kt) → Gradle</code> puis <code>Shared.xcframework reconstruit</code> ; build suivant : <code>Shared.xcframework à jour</code>. Le bundle de tests dépend désormais de l&#39;app (ordre de build), sinon il compilait contre l&#39;ancien framework pendant que Gradle tournait.</p><h2 id="tokens-d-espacement-android" tabindex="-1">Tokens d&#39;espacement Android <a class="header-anchor" href="#tokens-d-espacement-android" aria-label="Permalink to &quot;Tokens d&#39;espacement Android&quot;">​</a></h2><p><code>PosSpacing</code> (xs 4 · s 8 · m 16 · l 24 · xl 32, depuis <code>DesignTokenFactory.SPACING</code> partagé) : 116 <code>dp</code> codés en dur remplacés dans 23 écrans (<code>padding</code>, <code>spacedBy</code>, <code>Spacer</code>) ; les tailles fixes (icônes, boutons, colonnes) restent en <code>dp</code>. Aucun changement visuel attendu (mêmes valeurs) — les captures Android ci-dessus sont prises avec le build migré.</p><h2 id="pieges-rencontres" tabindex="-1">Pièges rencontrés <a class="header-anchor" href="#pieges-rencontres" aria-label="Permalink to &quot;Pièges rencontrés&quot;">​</a></h2><ul><li><code>bmgr</code> : le Backup Manager de l&#39;émulateur est désactivé par défaut (<code>bmgr enable true</code>, transport local) ; <code>adb backup</code> ouvre une boîte de confirmation sur l&#39;appareil à fermer ensuite (BACK).</li><li><code>BuildConfig.VERSION_NAME</code> exige <code>buildFeatures.buildConfig = true</code> (AGP 8).</li><li><code>@TestPropertySource</code> sur un test d&#39;intégration crée un second contexte Spring : acceptable pour un cas (la minimale) ; les autres tests envoient désormais <code>X-App-Version</code> comme les vraies apps, sinon 426 dès qu&#39;une minimale est fixée dans <code>application.yml</code>.</li><li>Redémarrer <code>bootRun</code> avec une variable d&#39;environnement : tuer le <code>java</code> qui écoute sur 8080 et attendre que le port soit libre, sinon le nouveau démarrage échoue en silence et l&#39;ancien serveur continue de répondre.</li></ul></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-dette-technique/android-02-mise-a-jour-requise.png" target="_blank"><img src="'+t+'" alt="android-02-mise-a-jour-requise.png" loading="lazy"></a><figcaption>android-02-mise-a-jour-requise.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-dette-technique/ios-02-mise-a-jour-requise.png" target="_blank"><img src="'+r+'" alt="ios-02-mise-a-jour-requise.png" loading="lazy"></a><figcaption>ios-02-mise-a-jour-requise.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-dette-technique/web-01-dashboard-latence-des-caisses.jpg" target="_blank"><img src="'+o+`" alt="web-01-dashboard-latence-des-caisses.jpg" loading="lazy"></a><figcaption>web-01-dashboard-latence-des-caisses.jpg</figcaption></figure></div><h2 id="traces-api-journaux-bases" tabindex="-1">Traces (API, journaux, bases) <a class="header-anchor" href="#traces-api-journaux-bases" aria-label="Permalink to &quot;Traces (API, journaux, bases)&quot;">​</a></h2><details><summary>android-01-restauration-sauvegarde-refusee.txt</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Restauration de sauvegarde — Android (émulateur, Backup Manager + transport local) — lot 2.27, 30/10/2026</span></span>
<span class="line"><span># But : prouver par une VRAIE sauvegarde / restauration (et pas seulement les drapeaux du manifeste) qu&#39;aucune donnée de la caisse ne sort ni ne revient.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ bmgr enable true</span></span>
<span class="line"><span>Backup Manager now enabled</span></span>
<span class="line"><span>$ bmgr transport com.android.localtransport/.LocalTransport</span></span>
<span class="line"><span>Selected transport com.android.localtransport/.LocalTransport (formerly com.google.android.gms/.backup.BackupTransportService)</span></span>
<span class="line"><span>$ bmgr backupnow pos.android</span></span>
<span class="line"><span>Running incremental backup for 1 requested packages.</span></span>
<span class="line"><span>Package pos.android with result: Backup is not allowed</span></span>
<span class="line"><span>Backup finished with result: Success</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ bmgr list sets</span></span>
<span class="line"><span>  1 : Local disk image</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ adb backup -f pos.ab pos.android   (ancien mécanisme ; allowBackup=false → archive vide)</span></span>
<span class="line"><span>WARNING: adb backup is deprecated and may be removed in a future release</span></span>
<span class="line"><span>Now unlock your device and confirm the backup operation...</span></span>
<span class="line"><span>   taille de l archive : 0 octets (en-tête seul = rien d exporté)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ dumpsys backup | grep pos.android</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ bmgr restore &lt;jeu&gt; pos.android   (restauration vers l&#39;app)</span></span>
<span class="line"><span>   aucun jeu de sauvegarde ne contient pos.android (rien à restaurer)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls databases (base locale intacte après la tentative)</span></span>
<span class="line"><span>total 648</span></span>
<span class="line"><span>drwxrwx--x 2 u0_a226 u0_a226   4096 2026-10-29 23:58 .</span></span>
<span class="line"><span>drwx------ 7 u0_a226 u0_a226   4096 2026-10-30 00:39 ..</span></span>
<span class="line"><span>-rw-rw---- 1 u0_a226 u0_a226 638976 2026-10-30 22:43 pos.db</span></span>
<span class="line"><span>-rw-rw---- 1 u0_a226 u0_a226      0 2026-10-30 22:43 pos.db-journal</span></span>
<span class="line"><span>$ bmgr enable false</span></span>
<span class="line"><span>Backup Manager now disabled</span></span></code></pre></div></details><details><summary>api-01-version-minimale-426-telemetrie.txt</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>== Version minimale d&#39;app (RG-SYNC-27) — serveur : pos.app.min-version = 0.1.0</span></span>
<span class="line"><span>  GET /sync/pull  X-App-Version: 0.0.9  → HTTP 426 {&quot;code&quot;:&quot;UPGRADE_REQUIRED&quot;,&quot;minAppVersion&quot;:&quot;0.1.0&quot;,&quot;appVersion&quot;:&quot;0.0.9&quot;,&quot;message&quot;:&quot;Mise à jour requise : version minimale 0.1.0 — l&#39;app continue hors ligne, synchronisation suspendue&quot;}</span></span>
<span class="line"><span>  GET /sync/pull  sans X-App-Version     → HTTP 426 (ancienne app muette = refusée)</span></span>
<span class="line"><span>  GET /sync/pull  X-App-Version: 0.1.0  → HTTP 200 (app à jour)</span></span>
<span class="line"><span>  GET /pos/lan-key X-App-Version: 0.0.1 → HTTP 426 (tous les appels appareil sont couverts)</span></span>
<span class="line"><span>  GET /stores/{id}/supervision/alerts (JWT back-office, sans version) → HTTP 200 (le back-office n&#39;est pas concerné)</span></span>
<span class="line"><span>== Télémétrie de latence (spec 00 §6.1) — rapport d&#39;un appareil puis lecture back-office</span></span>
<span class="line"><span>  POST /pos/telemetry/latency (Preuve API, p95 recherche 142 ms) → HTTP 202</span></span>
<span class="line"><span>  POST /pos/telemetry/latency (2e rapport, p95 recherche 38 ms) → HTTP 202</span></span>
<span class="line"><span>  GET /stores/{id}/telemetry/latency → 1 appareil(s), 0 action(s) hors budget</span></span>
<span class="line"><span>    Preuve API 2.23 api 0.1.0 · search · n=55 · p50 9 ms · p95 38 ms · max 90 ms · dans le budget</span></span>
<span class="line"><span>    Preuve API 2.23 api 0.1.0 · add_to_cart · n=120 · p50 4 ms · p95 12 ms · max 30 ms · dans le budget</span></span></code></pre></div></details><details><summary>ios-01-exclusion-sauvegarde-attributs-fichiers.txt</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Exclusion de sauvegarde — iOS (simulateur iPhone 17 Pro, conteneur réel de l&#39;app) — lot 2.27, 30/10/2026</span></span>
<span class="line"><span># But : vérifier sur les FICHIERS (attribut étendu posé par isExcludedFromBackup), pas seulement dans le code,</span></span>
<span class="line"><span># que les bases de la caisse ne partent dans aucune sauvegarde iCloud / Finder ; une restauration sur un autre</span></span>
<span class="line"><span># appareil repart donc d&#39;une app vide → ré-appairage + resynchronisation depuis le serveur (spec 10 §4.5).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls &quot;Library/Application Support/databases&quot;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>   256 .</span></span>
<span class="line"><span>   96 ..</span></span>
<span class="line"><span>   4096 demo.db</span></span>
<span class="line"><span>   32768 demo.db-shm</span></span>
<span class="line"><span>   527392 demo.db-wal</span></span>
<span class="line"><span>   397312 pos.db</span></span>
<span class="line"><span>   32768 pos.db-shm</span></span>
<span class="line"><span>   3085912 pos.db-wal</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ xattr -l &quot;Library/Application Support/databases&quot;</span></span>
<span class="line"><span>   com.apple.metadata:com_apple_backup_excludeItem: com.apple.MobileBackup</span></span>
<span class="line"><span>   → exclu de la sauvegarde (com_apple_backup_excludeItem présent)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ xattr -l &quot;Library/Application Support/databases/pos.db&quot;</span></span>
<span class="line"><span>   com.apple.metadata:com_apple_backup_excludeItem: com.apple.MobileBackup</span></span>
<span class="line"><span>   com.apple.provenance: </span></span>
<span class="line"><span>   → exclu de la sauvegarde (com_apple_backup_excludeItem présent)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ xattr -l &quot;Library/Application Support/databases/pos.db-wal&quot;</span></span>
<span class="line"><span>   com.apple.metadata:com_apple_backup_excludeItem: com.apple.MobileBackup</span></span>
<span class="line"><span>   com.apple.provenance: </span></span>
<span class="line"><span>   → exclu de la sauvegarde (com_apple_backup_excludeItem présent)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ Preferences / Keychain : la clé du cache d&#39;auth est kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly (jamais restaurée ailleurs) — cf. CacheAuthChiffreTests / PosAppKeychainTests</span></span></code></pre></div></details>`,9)])])}const v=a(i,[["render",c]]);export{h as __pageData,v as default};
